// Package bundled embeds the Redocly-bundled OpenAPI document. The JSON is
// generated by scripts/bundle-openapi.mjs; never edit it by hand. HTTP serving
// lives in the server (internal/api), not here: this tree is the MIT contract.
package bundled

import (
	_ "embed"

	"github.com/zitadel/nextgen/api/client"
)

//go:embed openapi.json
var document []byte

// Path is where the server mounts the document (ADR 077 prefix).
var Path = client.PathPrefix + "/openapi.json"

// Document returns the embedded OpenAPI JSON bytes.
func Document() []byte {
	return document
}
